            {waiting ? "Checking…" : busy ? "Starting…" : "Run checks now"}
          </button>
        )}
        {rep.ready && !waiting && rep.business.site_url && (
          <a className="btn btn-ghost" href={rep.business.site_url} target="_blank" rel="noreferrer">
            Open my website
          </a>
        )}
        {!launched && (
          <a className="btn btn-primary" href={`#/b/${businessId}/launch`}>
            Launch my website →
          </a>
        )}
      </div>
      {error && <ErrorBox error={error} />}

      {run && run.status === "done" && (
        <>
          <h2>What we checked</h2>
          <p className="muted">
            {run.trigger === "launch" ? "Right after your launch" : "When you pressed “Run checks now”"},{" "}
            {time(run.started_at)}.
          </p>
          <ul className="card rows checks">
            {run.checks.map((c, i) => (
              <CheckLine
                key={`${run.id}-${c.check}`}
                c={c}
                doctor={run.repairs.find((r) => r.check === c.check)?.attempts[0]?.explanation ?? ""}
                state={!playing || i < cur.index ? "final" : i > cur.index ? "waiting" : cur.phase}
                onTyped={() =>
      </section>

      {saveError && <ErrorBox error={saveError} />}
      <div className="actions">
        <button className="btn btn-primary" type="submit" disabled={saving}>
          {saving ? "Saving…" : "Save"}
        </button>
        {biz.site_url && (
          <a className="btn btn-ghost" href={biz.site_url} target="_blank" rel="noreferrer">
            View my website
          </a>
        )}
        {!dirty && biz.status !== "live" && (
          <a className="btn btn-primary" href={`#/b/${id}/launch`}>
            Launch my website →
            {busy ? "Resuming…" : "Resume"}
          </button>
        )}
        {finished && (
          <a className="btn btn-primary" href={`#/b/${businessId}/report`}>
            See your launch report →
          </a>
        )}
        {finished && plan.site_url && (
