            href={plan.site_url}
            target="_blank"
            rel="noreferrer"
          >
            Open my website
          </a>
        )}
        <a className="btn btn-ghost" href={`#/b/${plan.business_id}`}>
          Back to your details
        </a>
      </div>
    </header>
